// Serves one rendered file from <data_dir>/out so Meta (image_url / cover_url) and the report email can fetch it.
// Only plain file names are accepted (letters, digits, _ . -; .jpg/.jpeg/.mp4), so nothing outside out/ can be read.
const fs = require('fs');
const q = $('Media Webhook').first().json.query || {};
const f = String(q.f || '');
if (!/^[A-Za-z0-9_.-]+\.(jpe?g|mp4)$/.test(f) || f.includes('..')) { throw new Error('invalid file name'); }
const p = $('Config').first().json.data_dir + '/out/' + f;
const buf = fs.readFileSync(p);
const mime = f.endsWith('.mp4') ? 'video/mp4' : 'image/jpeg';
const bin = await this.helpers.prepareBinaryData(buf, f, mime);
return { json: { file: f, mime }, binary: { data: bin } };
